use super::misc::opposite_vertex;
use super::misc::rc3;
use super::tet::tet_centroid;
use super::tet::tet_faces;
use crate::mesh::types::Point;
use std::collections::HashMap;

/// Whether `anchor` lies strictly in the interior half-space of every outer
/// face of the tetrahedral cavity described by `remove`.
///
/// This is the visibility/kernel condition required before coning each outer
/// face to a single new point. It intentionally rejects non-star cavities:
/// preserving only the sorted boundary face set does not prove the resulting
/// tetrahedra are non-overlapping.
pub(super) fn cavity_anchor_sees_boundary(
    points: &[Point],
    tets: &[[usize; 4]],
    remove: &[usize],
    anchor: Point,
) -> bool {
    let mut owners: HashMap<[usize; 3], (usize, usize)> = HashMap::new();
    for &tet_index in remove {
        for face in tet_faces(tets[tet_index]) {
            owners
                .entry(face)
                .and_modify(|(_, count)| *count += 1)
                .or_insert((tet_index, 1));
        }
    }

    !owners.is_empty()
        && owners.into_iter().all(|(face, (owner, count))| {
            if count != 1 {
                return true;
            }
            let Some(opposite) = opposite_vertex(tets[owner], face) else {
                return false;
            };
            let [a, b, c] = face;
            let interior = robust::orient3d(
                rc3(points[a]),
                rc3(points[b]),
                rc3(points[c]),
                rc3(points[opposite]),
            );
            let candidate =
                robust::orient3d(rc3(points[a]), rc3(points[b]), rc3(points[c]), rc3(anchor));
            interior != 0.0 && candidate != 0.0 && interior.signum() == candidate.signum()
        })
}

pub(super) fn cavity_side_anchors(
    points: &[Point],
    tets: &[[usize; 4]],
    remove: &[usize],
    facet: [usize; 3],
    side: i8,
) -> Vec<Point> {
    remove
        .iter()
        .map(|&index| tet_centroid(points, tets[index]))
        .filter(|point| {
            let signed = robust::orient3d(
                rc3(points[facet[0]]),
                rc3(points[facet[1]]),
                rc3(points[facet[2]]),
                rc3(*point),
            );
            (side > 0 && signed > 0.0) || (side < 0 && signed < 0.0)
        })
        .collect()
}
